use crate::aap::caps::{http_client, notifier};

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved
/// characters pass through; every other byte becomes `%XX`).
fn encode_query(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup, on every call. The digest's free text is its
        // overview. `fetch` returns transport failures as values, so a down
        // metadata service does not fail the run; the enrichment record is
        // not used, so the output is unchanged by this call.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        // Publish: notify the channel with the digest's date and overview.
        let message = format!("{}\n{}", composed.date, composed.overview);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
